// Extract the best contact from Apollo response
// Logic: prefer CEO for small companies, Head of Product / CPO for larger ones

const apolloResponse = $json;
const jobData = $node['Filter: Score >= 8 and No Outreach Yet'].json;

const people = apolloResponse?.people || [];

if (people.length === 0) {
  // No contact found — skip this job
  return [
    {
      json: {
        ...jobData,
        _skipOutreach: true,
        _skipReason: 'No contact found in Apollo',
        contactName: '',
        contactTitle: '',
        contactEmail: '',
        contactLinkedIn: ''
      }
    }
  ];
}

// Priority order: CEO > CPO > Head of Product > VP Product > any
const titlePriority = ['ceo', 'chief executive', 'chief product', 'cpo', 'head of product', 'vp product', 'vp of product'];

const ranked = people
  .filter(p => p.email && p.email !== 'email_not_found@email.com')
  .sort((a, b) => {
    const aTitle = (a.title || '').toLowerCase();
    const bTitle = (b.title || '').toLowerCase();
    const aRank = titlePriority.findIndex(t => aTitle.includes(t));
    const bRank = titlePriority.findIndex(t => bTitle.includes(t));
    return (aRank === -1 ? 99 : aRank) - (bRank === -1 ? 99 : bRank);
  });

const best = ranked[0] || people[0];

return [
  {
    json: {
      // Carry forward all job fields
      Date: jobData.Date,
      Company: jobData.Company,
      Title: jobData.Title,
      Score: jobData.Score,
      'Fit Reasons': jobData['Fit Reasons'],
      'Application URL': jobData['Application URL'],
      'Tailored Headline': jobData['Tailored Headline'],
      'Tailored Summary': jobData['Tailored Summary'],
      // Contact info
      contactName: `${best.first_name || ''} ${best.last_name || ''}`.trim(),
      contactTitle: best.title || '',
      contactEmail: best.email || '',
      contactLinkedIn: best.linkedin_url || '',
      contactOrg: best.organization?.name || jobData.Company,
      contactOrgSize: best.organization?.num_employees || 'unknown',
      _skipOutreach: false
    }
  }
];

// Note: After ZeroBounce node, $json is the ZeroBounce response.
// Retrieve the job/contact data from the previous node.
const zbResponse = $json;
const contactData = $node['Extract Best Contact'].json;

const SYSTEM_PROMPT = `You are an expert cold email copywriter specializing in senior executive outreach.

You write concise, personalized, non-salesy cold emails on behalf of Hersh Malik — a senior fintech and AI product leader.

Email rules:
1. Subject line must reference something specific about the company (product, milestone, mission, or market position)
2. Opening line establishes shared context: Columbia MBA, fintech background, DC area, or mutual connection if obvious
3. One sentence on what Hersh is exploring (senior PM / TPM / Director of Product roles)
4. Two sentences matching Hersh's specific background to their company's domain
5. One soft ask for a 15-minute conversation
6. Sign off as Hersh Malik with LinkedIn URL: linkedin.com/in/hershmalik
7. Total email body MUST be under 150 words
8. DO NOT use generic phrases like 'I came across your company' or 'I am reaching out because'

Hersh's background to draw from:
- 12 years product and program leadership at Goldman Sachs, Morgan Stanley, and Coinbase
- Deep expertise in fintech infrastructure, compliance tech, and regulatory systems
- Production RAG systems, MCP agentic workflows, n8n automation
- Columbia MBA
- Washington DC metro area
- Target: $250K+ base, Principal PM / Senior Director Product / Lead PM / TPM

Return ONLY valid JSON in this exact schema (no markdown, no extra text):
{
  "subject": "<specific, personalized subject line>",
  "body": "<complete email body under 150 words>"
}`;

const userMessage = `Write a cold outreach email with these details:

TO: ${contactData.contactName} (${contactData.contactTitle})
COMPANY: ${contactData.Company}
JOB HERSH IS TARGETING: ${contactData.Title}
COMPANY SIZE: ~${contactData.contactOrgSize} employees

JOB FIT CONTEXT (why Hersh is a strong match):
${contactData['Fit Reasons'] || 'Senior fintech and AI product leader background'}

TAILORED HEADLINE FOR THIS ROLE:
${contactData['Tailored Headline'] || ''}`;

const requestBody = {
  model: 'claude-sonnet-4-20250514',
  max_tokens: 600,
  system: SYSTEM_PROMPT,
  messages: [
    { role: 'user', content: userMessage }
  ]
};

return [
  {
    json: {
      ...contactData,
      _emailRequestBody: JSON.stringify(requestBody),
      _emailAddress: zbResponse.address || contactData.contactEmail
    }
  }
];

const apiResponse = $json;
const contactData = $node['Prepare Email Generation Request'].json;

let subject = '';
let body = '';
let emailError = null;

try {
  if (apiResponse.error) {
    throw new Error(`Claude API error: ${apiResponse.error.message}`);
  }

  const content = apiResponse?.content?.[0]?.text;
  if (!content) throw new Error('No content in Claude response');

  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(cleaned);

  subject = parsed.subject || '';
  body = parsed.body || '';

  // Safety check: reject emails over 200 words
  const wordCount = body.split(/\s+/).length;
  if (wordCount > 200) {
    body = body.split(/\s+/).slice(0, 175).join(' ') + '...';
  }

} catch (err) {
  emailError = err.message;
}

return [
  {
    json: {
      ...contactData,
      emailSubject: subject,
      emailBody: body,
      emailError,
      toEmail: contactData._emailAddress
    }
  }
];
